WITH base AS ( SELECT * FROM ( SELECT c.*, COALESCE(NULLIF(c.parent_asin, ''), c.asin) AS product_key, ROW_NUMBER() OVER ( PARTITION BY c.marketplace, c.seller_name, COALESCE(NULLIF(c.parent_asin, ''), c.asin) ORDER BY CASE WHEN c.week_tag IS NULL OR c.week_tag = '' THEN 1 ELSE 0 END ASC, c.week_tag DESC, CASE WHEN c.updated_at IS NULL THEN 1 ELSE 0 END ASC, c.updated_at DESC, c.id DESC ) AS rn FROM competitor_products_clean c WHERE c.m01_active = 1
AND c.marketplace = #{marketplace}
AND c.effective_week_tag = #{effectiveWeekTag}
AND c.seller_name IS NOT NULL AND TRIM(c.seller_name) != '' AND LOWER(TRIM(c.seller_name)) NOT IN ('amazon', 'null') AND c.asin IS NOT NULL AND c.asin != '' ) ranked WHERE rn = 1 ) SELECT 'M01' AS methodId, b.seller_name AS sellerName, b.marketplace AS marketplace, COUNT(*) AS hitCount, ROUND(AVG(b.price), 2) AS avgPrice, MIN(b.price) AS minPrice, MAX(b.price) AS maxPrice, SUM(CASE WHEN UPPER(TRIM(COALESCE(b.sales_tier, 'UNKNOWN'))) = 'A' THEN 1 ELSE 0 END) AS salesTierACount, SUM(CASE WHEN UPPER(TRIM(COALESCE(b.sales_tier, 'UNKNOWN'))) = 'B' THEN 1 ELSE 0 END) AS salesTierBCount, SUM(CASE WHEN UPPER(TRIM(COALESCE(b.sales_tier, 'UNKNOWN'))) = 'C' THEN 1 ELSE 0 END) AS salesTierCCount, SUM(CASE WHEN UPPER(TRIM(COALESCE(b.sales_tier, 'UNKNOWN'))) = 'D' THEN 1 ELSE 0 END) AS salesTierDCount, SUM(CASE WHEN b.sales_tier IS NULL OR TRIM(b.sales_tier) = '' OR UPPER(TRIM(b.sales_tier)) NOT IN ('A', 'B', 'C', 'D') THEN 1 ELSE 0 END) AS salesTierUnknownCount, ( SELECT SUBSTRING_INDEX(b2.node_label_path, ':', -1) FROM base b2 WHERE b2.marketplace = b.marketplace AND b2.seller_name = b.seller_name AND b2.node_label_path IS NOT NULL AND b2.node_label_path != '' GROUP BY SUBSTRING_INDEX(b2.node_label_path, ':', -1) ORDER BY COUNT(*) DESC LIMIT 1 ) AS topCategory FROM base b GROUP BY b.seller_name, b.marketplace HAVING COUNT(*) >= #{minCount} ORDER BY hitCount DESC, avgPrice ASC LIMIT #{limit}

WITH ranked AS ( SELECT c.marketplace, c.seller_name, c.price, c.node_label_path, COALESCE(NULLIF(c.parent_asin, ''), c.asin) AS product_key, ROW_NUMBER() OVER ( PARTITION BY c.marketplace, c.seller_name, COALESCE(NULLIF(c.parent_asin, ''), c.asin) ORDER BY CASE WHEN c.updated_at IS NULL THEN 1 ELSE 0 END ASC, c.updated_at DESC, c.id DESC ) AS rn FROM competitor_products_clean c WHERE c.effective_week_tag = #{effectiveWeekTag}
AND c.marketplace = #{marketplace}
AND c.seller_name IS NOT NULL AND TRIM(c.seller_name) != '' AND LOWER(TRIM(c.seller_name)) NOT IN ('amazon', 'null') AND c.asin IS NOT NULL AND TRIM(c.asin) != '' ), base AS ( SELECT * FROM ranked WHERE rn = 1 ), shop_stats AS ( SELECT seller_name, marketplace, COUNT(*) AS hitCount, ROUND(AVG(price), 2) AS avgPrice, MIN(price) AS minPrice, MAX(price) AS maxPrice FROM base GROUP BY seller_name, marketplace ), category_counts AS ( SELECT seller_name, marketplace, SUBSTRING_INDEX(node_label_path, ':', -1) AS category_name, COUNT(*) AS category_count FROM base WHERE node_label_path IS NOT NULL AND TRIM(node_label_path) != '' GROUP BY seller_name, marketplace, SUBSTRING_INDEX(node_label_path, ':', -1) ), category_ranked AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY marketplace, seller_name ORDER BY category_count DESC, category_name ASC ) AS category_rank FROM category_counts ) SELECT 'ALL' AS methodId, s.seller_name AS sellerName, s.marketplace AS marketplace, s.hitCount, s.avgPrice, s.minPrice, s.maxPrice, cr.category_name AS topCategory FROM shop_stats s LEFT JOIN category_ranked cr ON cr.marketplace = s.marketplace AND cr.seller_name = s.seller_name AND cr.category_rank = 1 ORDER BY s.hitCount DESC, s.avgPrice ASC

SELECT 'M01' AS methodId,
#{marketplace} AS marketplace,
'ALL' AS marketplace,
c.effective_week_tag AS batchCode, 'competitor_products_clean' AS sourceTable, 'effective_week_tag' AS sourceWeekField, COUNT(DISTINCT CONCAT( c.marketplace, '|', c.seller_name, '|', COALESCE(NULLIF(c.parent_asin, ''), c.asin) )) AS productCount, COUNT(DISTINCT CONCAT(c.marketplace, '|', c.seller_name)) AS sellerCount, MAX(c.created_at) AS latestCreatedAt FROM competitor_products_clean c WHERE c.m01_active = 1 AND c.effective_week_tag IS NOT NULL AND c.effective_week_tag != '' AND c.seller_name IS NOT NULL AND TRIM(c.seller_name) != '' AND LOWER(TRIM(c.seller_name)) NOT IN ('amazon', 'null') AND c.asin IS NOT NULL AND c.asin != ''
AND c.marketplace = #{marketplace}
GROUP BY c.effective_week_tag ORDER BY MAX(c.created_at) DESC, c.effective_week_tag DESC LIMIT #{limit}

SELECT 'ALL' AS methodId,
#{marketplace} AS marketplace,
'ALL' AS marketplace,
c.effective_week_tag AS batchCode, 'competitor_products_clean' AS sourceTable, 'effective_week_tag' AS sourceWeekField, COUNT(DISTINCT CONCAT( c.marketplace, '|', c.seller_name, '|', COALESCE(NULLIF(c.parent_asin, ''), c.asin) )) AS productCount, COUNT(DISTINCT CONCAT(c.marketplace, '|', c.seller_name)) AS sellerCount, MAX(c.created_at) AS latestCreatedAt FROM competitor_products_clean c WHERE c.effective_week_tag IS NOT NULL AND c.effective_week_tag != '' AND c.seller_name IS NOT NULL AND TRIM(c.seller_name) != '' AND LOWER(TRIM(c.seller_name)) NOT IN ('amazon', 'null') AND c.asin IS NOT NULL AND TRIM(c.asin) != ''
AND c.marketplace = #{marketplace}
GROUP BY c.effective_week_tag ORDER BY MAX(c.created_at) DESC, c.effective_week_tag DESC LIMIT #{limit}

mapper.update:
UPDATE competitor_products
SET listing_days = #{unknownListingDays}
WHERE marketplace = #{marketplace}
  AND (
      HEX(source) = 'E696B0E59381E6A69C'
      OR LOWER(source) LIKE '%new%'
  )
  AND (available_date IS NULL OR available_date <= 0)
  AND (listing_days IS NULL OR listing_days >= #{listingDaysMax})

UPDATE competitor_products cp SET cp.m01_active = CASE WHEN ( HEX(cp.source) = 'E696B0E59381E6A69C' OR LOWER(cp.source) LIKE '%new%' ) AND cp.price IS NOT NULL AND cp.price >= #{priceMin} AND cp.price <= #{priceMax} AND cp.weight_g IS NOT NULL AND cp.weight_g < #{weightMax} AND ( CASE WHEN cp.available_date IS NOT NULL AND cp.available_date > 0 THEN DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) ELSE COALESCE(cp.listing_days, #{unknownListingDays}) END ) < #{listingDaysMax} AND ( ( cp.units IS NOT NULL AND ( (( CASE WHEN cp.available_date IS NOT NULL AND cp.available_date > 0 THEN DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) ELSE COALESCE(cp.listing_days, #{unknownListingDays}) END ) <= 30 AND cp.units >= #{sales30}) OR (( CASE WHEN cp.available_date IS NOT NULL AND cp.available_date > 0 THEN DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) ELSE COALESCE(cp.listing_days, #{unknownListingDays}) END ) <= 60 AND cp.units >= #{sales60}) OR (( CASE WHEN cp.available_date IS NOT NULL AND cp.available_date > 0 THEN DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) ELSE COALESCE(cp.listing_days, #{unknownListingDays}) END ) <= 90 AND cp.units >= #{sales90}) ) )
OR (cp.bsr IS NOT NULL AND cp.bsr > 0 AND cp.bsr < #{bsrMax})
) THEN 1 ELSE 0 END WHERE cp.marketplace = #{marketplace}

UPDATE competitor_products_clean
SET listing_days = #{unknownListingDays}
WHERE marketplace = #{marketplace}
  AND (
      HEX(source) = 'E696B0E59381E6A69C'
      OR LOWER(source) LIKE '%new%'
  )
  AND (available_date IS NULL OR available_date <= 0)
  AND (listing_days IS NULL OR listing_days >= #{listingDaysMax})

UPDATE competitor_products
SET m01_active = 0
WHERE marketplace = #{marketplace}
  AND m01_active = 1
  AND available_date > 0
  AND DATEDIFF(NOW(), FROM_UNIXTIME(available_date / 1000)) >= #{listingDaysMax}

UPDATE competitor_products_clean
SET m01_active = 0
WHERE marketplace = #{marketplace}
  AND m01_active = 1
  AND available_date > 0
  AND DATEDIFF(NOW(), FROM_UNIXTIME(available_date / 1000)) >= #{listingDaysMax}
